# Generate player.tscn and main.tscn via code so they're valid Godot scene files
func _run():
    generate_player()
    generate_main()
    print("Generated scenes.")

func generate_player():
    var player = Node2D.new()
    player.name = "Player"
    player.script = load("res://player.gd")

    var sync = MultiplayerSynchronizer.new()
    sync.name = "MultiplayerSynchronizer"
    sync.root_path = NodePath("..")
    sync.replication_config = SceneReplicationConfig.new()
    sync.replication_config.add_property("Player:position")
    sync.replication_config.set_property_spawn("Player:position", true)
    sync.replication_config.set_property_sync("Player:position", true)
    sync.replication_config.set_property_watch("Player:position", true)

    # Actually simpler: just use add_property
    sync.replication_config = SceneReplicationConfig.new()
    sync.replication_config.add_property("position")

    player.add_child(sync)
    sync.owner = player

    var scene = PackedScene.new()
    var res = scene.pack(player)
    assert(res == OK)
    var err = ResourceSaver.save(scene, "res://player.tscn")
    assert(err == OK)

func generate_main():
    var root = Node2D.new()
    root.name = "Main"
    root.script = load("res://main.gd")
    var scene = PackedScene.new()
    var res = scene.pack(root)
    assert(res == OK)
    var err = ResourceSaver.save(scene, "res://main.tscn")
    assert(err == OK)

_run()
