extends Node2D

# Lobby state collected from each peer after pumping frames.
var _server: Dictionary = {"unique_id": 1, "peers": [], "players": {}}
var _clients: Array = []  # In CLI client order
var _out_path: String = "output.json"
var _score_deltas: Array = []
var _clients_requested: int = 0
var _port: int = 7000
var _frames: int = 0

var _server_peer: ENetMultiplayerPeer
var _client_peers: Array = []  # One ENetClient peer per client

# Client-side: map each client peer ID to its local unique_id after connection.
# We use connection order to assign deterministic IDs (2, 3, ...).
var _client_id_map: Array = []  # index = client spawn order -> peer_id

func _ready():
    await get_tree().process_frame
    _parse_args()
    _start_lobby()
    await _pump_frames(_frames)
    _write_final_state()
    get_tree().quit(0)

func _parse_args():
    var args = OS.get_cmdline_user_args()
    var i = 0
    while i < args.size():
        var arg = args[i]
        if arg.begins_with("--port="):
            _port = int(arg.trim_prefix("--port="))
        elif arg.begins_with("--clients="):
            _clients_requested = int(arg.trim_prefix("--clients="))
        elif arg.begins_with("--frames="):
            _frames = int(arg.trim_prefix("--frames="))
        elif arg.begins_with("--score-deltas="):
            for part in arg.trim_prefix("--score-deltas=").split(","):
                if part.strip_edges() != "":
                    _score_deltas.append(int(part.strip_edges()))
        elif arg.begins_with("--out="):
            _out_path = arg.trim_prefix("--out=")
        i += 1
    print("Lobby config: port=", _port, " clients=", _clients_requested, " frames=", _frames, " deltas=", _score_deltas, " out=", _out_path)

func _start_lobby():
    # Shared player container.
    var players = Node2D.new()
    players.name = "Players"
    add_child(players)

    # Server MP on /root (default server).
    _server_peer = ENetMultiplayerPeer.new()
    _server_peer.create_server(_port, _clients_requested + 1)
    multiplayer.multiplayer_peer = _server_peer

    # Server spawner.
    var s_spawn = MultiplayerSpawner.new()
    s_spawn.name = "Spawner"
    s_spawn.spawn_path = NodePath("/root/Players")
    s_spawn.add_spawnable_scene("res://player.tscn")
    add_child(s_spawn)

    # Spawn server's own player (auth 1).
    _spawn_player(1)

    # Spin up N clients in the same process with separate MultiplayerAPIs.
    for i in range(_clients_requested):
        var c_root = Node2D.new()
        c_root.name = "Client%d" % i
        add_child(c_root)

        var c_peer = ENetMultiplayerPeer.new()
        c_peer.create_client("127.0.0.1", _port)
        var c_api = MultiplayerAPI.create_default_interface()
        c_api.multiplayer_peer = c_peer
        get_tree().set_multiplayer(c_api, NodePath("/root/" + c_root.name))

        _client_peers.append({"peer": c_peer, "api": c_api, "root": c_root})

        # Client spawner to receive spawns from the server into the shared container.
        var c_spawn = MultiplayerSpawner.new()
        c_spawn.name = "Spawner"
        c_spawn.spawn_path = NodePath("/root/Players")
        c_spawn.add_spawnable_scene("res://player.tscn")
        c_root.add_child(c_spawn)

    # The server spawns a player for each connecting peer when connected.
    _server_peer.peer_connected.connect(_on_peer_connected)

func _spawn_player(peer_id: int):
    var p = load("res://player.tscn").instantiate()
    p.name = "Player%d" % peer_id
    p.set_multiplayer_authority(peer_id)
    # The authoritative peer should set its own initial position.
    if multiplayer.get_unique_id() == peer_id:
        p.position = Vector2(float(peer_id), float(peer_id))
    get_node("/root/Players").add_child(p)

func _on_peer_connected(id: int):
    # Server assigns player to the newly connected client peer.
    _spawn_player(id)

func _pump_frames(n: int) -> void:
    for i in range(n):
        # Clients need to trigger their RPCs once their player is ready.
        _check_client_rpc_conditions()
        await get_tree().process_frame

func _check_client_rpc_conditions():
    var players = get_node("/root/Players")
    for i in range(_client_peers.size()):
        var c = _client_peers[i]
        var c_api = c.api
        var my_id = c_api.get_unique_id()
        if my_id == 0: continue  # not yet connected

        # Has this client already called its RPC?
        if _client_already_called_rpc(i): continue

        # Wait for the client to see all N+1 players.
        if players.get_child_count() < _clients_requested + 1:
            continue
        # Wait until its own player has arrived.
        var my_player = _find_player_by_authority(players, my_id)
        if my_player == null:
            continue

        # The delta for this client.
        var delta = 0
        if i < _score_deltas.size():
            delta = _score_deltas[i]

        print("Client index ", i, " (id=", my_id, ") invoking update_score(", delta, ") on ", my_player.get_path())
        # Note: the RPC is called through the client's API on its player node.
        my_player.update_score.rpc(delta)
        _mark_client_called_rpc(i)

# Helper to track which client has fired its RPC (client index -> bool)
var _rpc_fired = {}
func _client_already_called_rpc(idx: int) -> bool:
    return _rpc_fired.has(idx)
func _mark_client_called_rpc(idx: int):
    _rpc_fired[idx] = true

func _find_player_by_authority(container: Node, auth: int) -> Node:
    for c in container.get_children():
        if c.has_method("get_multiplayer_authority") and c.get_multiplayer_authority() == auth:
            return c
    return null

func _write_final_state():
    # Gather server state from the server perspective.
    _server.peers = _get_sorted_client_peer_ids()
    _server.players = _collect_players(multiplayer)

    # Gather each client's state from that client's perspective.
    _clients = []
    for c in _client_peers:
        var c_api = c.api
        var c_state = {"unique_id": c_api.get_unique_id(), "peers": _get_client_peers(c_api), "players": _collect_players(c_api)}
        _clients.append(c_state)

    var root_dict = {"server": _server, "clients": _clients}
    var json_text = JSON.stringify(root_dict, "  ")
    var f = FileAccess.open(_out_path, FileAccess.WRITE)
    assert(f != null, "Failed to open output file: " + _out_path)
    f.store_string(json_text)
    f.close()
    print("Wrote final state to ", _out_path, ":\n", json_text)

func _collect_players(api: MultiplayerAPI) -> Dictionary:
    var players = get_node("/root/Players")
    var result = {}
    for p in players.get_children():
        var pid = p.get_multiplayer_authority()
        result[str(pid)] = {"authority": pid, "position": [p.position.x, p.position.y], "score": p.score}
    return result

func _get_sorted_client_peer_ids() -> Array:
    var ids = []
    for c in _client_peers:
        var id = c.api.get_unique_id()
        if id != 0:
            ids.append(id)
    ids.sort()
    return ids

func _get_client_peers(c_api: MultiplayerAPI) -> Array:
    var my = c_api.get_unique_id()
    if my == 0: return []
    var ids = []
    # All other peers = server(1) + all other clients.
    ids.append(1)
    for c in _client_peers:
        var id = c.api.get_unique_id()
        if id != 0 and id != my:
            ids.append(id)
    ids.sort()
    return ids

